ALTER TABLE projects ADD COLUMN IF NOT EXISTS production_status TEXT NOT NULL DEFAULT 'story';
ALTER TABLE projects ADD COLUMN IF NOT EXISTS data_mode TEXT NOT NULL DEFAULT 'production' CHECK(data_mode IN ('production','fixture'));
ALTER TABLE films ADD COLUMN IF NOT EXISTS timeline_version INTEGER NOT NULL DEFAULT 0;
ALTER TABLE script_revisions ADD COLUMN IF NOT EXISTS title TEXT;
UPDATE script_revisions r SET title=u.title FROM script_units u WHERE r.unit_id=u.id AND r.title IS NULL;
ALTER TABLE ai_proposals ADD COLUMN IF NOT EXISTS edit_version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE assets ADD COLUMN IF NOT EXISTS identity_name TEXT;
ALTER TABLE asset_revisions ADD COLUMN IF NOT EXISTS metadata JSONB NOT NULL DEFAULT '{}';
ALTER TABLE asset_revisions ADD COLUMN IF NOT EXISTS content_qa JSONB NOT NULL DEFAULT '{"status":"needs_review"}';
ALTER TABLE asset_candidates ADD COLUMN IF NOT EXISTS content_qa JSONB NOT NULL DEFAULT '{"status":"needs_review"}';
ALTER TABLE director_shots ADD COLUMN IF NOT EXISTS design JSONB NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS shot_revisions(id UUID PRIMARY KEY,shot_id UUID NOT NULL REFERENCES director_shots(id) ON DELETE CASCADE,revision_number INTEGER NOT NULL,snapshot JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(shot_id,revision_number));
INSERT INTO shot_revisions(id,shot_id,revision_number,snapshot) SELECT id,id,version,to_jsonb(s) FROM director_shots s ON CONFLICT(shot_id,revision_number) DO NOTHING;
ALTER TABLE generation_clips ADD COLUMN IF NOT EXISTS plan JSONB NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS clip_revisions(id UUID PRIMARY KEY,clip_id UUID NOT NULL REFERENCES generation_clips(id) ON DELETE CASCADE,revision_number INTEGER NOT NULL,snapshot JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(clip_id,revision_number));
ALTER TABLE media_files ADD COLUMN IF NOT EXISTS technical_qa JSONB;
ALTER TABLE media_files ADD COLUMN IF NOT EXISTS storage_backend TEXT NOT NULL DEFAULT 'local';
ALTER TABLE video_runs ADD COLUMN IF NOT EXISTS lease_token UUID;
ALTER TABLE video_runs ADD COLUMN IF NOT EXISTS lease_expires_at TIMESTAMPTZ;
ALTER TABLE video_runs ADD COLUMN IF NOT EXISTS heartbeat_at TIMESTAMPTZ;
ALTER TABLE video_runs ADD COLUMN IF NOT EXISTS submission_started_at TIMESTAMPTZ;
ALTER TABLE video_runs ADD COLUMN IF NOT EXISTS next_poll_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE renders ADD COLUMN IF NOT EXISTS lease_token UUID;
ALTER TABLE renders ADD COLUMN IF NOT EXISTS lease_expires_at TIMESTAMPTZ;
ALTER TABLE renders ADD COLUMN IF NOT EXISTS heartbeat_at TIMESTAMPTZ;
ALTER TABLE timeline_segments ADD COLUMN IF NOT EXISTS volume NUMERIC NOT NULL DEFAULT 1;
ALTER TABLE timeline_segments ADD COLUMN IF NOT EXISTS fade_in_seconds NUMERIC NOT NULL DEFAULT 0;
ALTER TABLE timeline_segments ADD COLUMN IF NOT EXISTS fade_out_seconds NUMERIC NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS timeline_revisions(id UUID PRIMARY KEY,film_id UUID NOT NULL REFERENCES films(id) ON DELETE CASCADE,revision_number INTEGER NOT NULL,snapshot JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(film_id,revision_number));
ALTER TABLE take_review_issues DROP CONSTRAINT IF EXISTS take_review_issues_target_kind_check;
ALTER TABLE take_review_issues ADD CONSTRAINT take_review_issues_target_kind_check CHECK(target_kind IN ('clip','shot','asset','take'));
CREATE INDEX IF NOT EXISTS ix_runs_due ON video_runs(status,next_poll_at);
